def convert_units_obs4mips(da):
    if da.name.endswith("_nobs"):
        return da

    with xr.set_options(keep_attrs=True):
            da *= 1.0e6
            da.attrs["units"] = "ppm"
    return da

def compute_coverage_obs4mips(da, missing_values=1.0e20, dim="time"):
    return (da != missing_values).sum(dim) / da.sizes[dim]

def compute_coverage_iasi(da, dim="time"):
    return (da > 0).sum(dim) / da.sizes[dim]

def aggregate_coverage_iasi(ds):
    da = ds["mtco2_nobs"].groupby("time.month").map(compute_coverage_iasi)
    da.attrs = {"long_name": "MTCO$_2$ Data Coverage"}
    return da.to_dataset(name="mtco2_coverage")

